#include<bits/stdc++.h>
using namespace std;

struct Edge {
    int to, cap, flow, cost;
    Edge() {}
    Edge(int to, int cap, int flow, int cost) : to(to), cap(cap), flow(flow), cost(cost) {}
};

vector<Edge> edges;
const int MAXN = 14043;
vector<int> adj[MAXN];
long long total_cost = 0;
long long dist[MAXN];
int parent[MAXN];
int parent_edge[MAXN];
int in_queue[MAXN];
const long long INF = (long long)(1e18);
int source = MAXN - 2;
int sink = MAXN - 1;

int residual(int idx) {
    return edges[idx].cap - edges[idx].flow;
}

void augment() {
    for (int i = 0; i < MAXN; ++i) {
        dist[i] = INF;
        parent[i] = -1;
        parent_edge[i] = -1;
        in_queue[i] = 0;
    }
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    in_queue[source] = 1;
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        in_queue[v] = 0;
        for (int idx : adj[v]) {
            if (!residual(idx)) continue;
            int c = edges[idx].cost;
            int to = edges[idx].to;
            if (dist[to] > dist[v] + c) {
                dist[to] = dist[v] + c;
                parent[to] = v;
                parent_edge[to] = idx;
                if (!in_queue[to]) {
                    in_queue[to] = 1;
                    q.push(to);
                }
            }
        }
    }
    int cur = sink;
    while (cur != source) {
        edges[parent_edge[cur]].flow++;
        edges[parent_edge[cur] ^ 1].flow--;
        cur = parent[cur];
    }
    total_cost += dist[sink];
}

void add_edge(int x, int y, int cap, int cost) {
    adj[x].push_back(edges.size());
    edges.push_back(Edge(y, cap, 0, cost));
    adj[y].push_back(edges.size());
    edges.push_back(Edge(x, 0, 0, -cost));
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        add_edge(source, x, 1, 0);
    }
    int T = 101;
    for (int i = 0; i < T; ++i)
        add_edge(0 + i * n, sink, k, i * c);
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        --x; --y;
        for (int t = 0; t < T - 1; ++t)
            for (int j = 0; j < k; ++j)
                add_edge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
        for (int t = 0; t < T - 1; ++t)
            for (int j = 0; j < k; ++j)
                add_edge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
    }
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < T - 1; ++t)
            add_edge(i + t * n, i + t * n + n, k, 0);
    for (int i = 0; i < k; ++i)
        augment();
    cout << total_cost << endl;
    return 0;
}
